import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

test('createInvoice creates a valid invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2025-01-15');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'ICON-SET');
  assert.equal(r.value.lines[0].name, 'Icon set (24 icons)');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[0].unitPrice, 980);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'ICON-SET');
  assert.equal(r.value.lines[1].sku, 'DES-HOUR');
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '01-15-2025',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports invalid date (nonexistent)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-30',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports date with wrong format (missing parts)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports missing lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports invalid quantity (float)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports invalid quantity (zero)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports invalid quantity (negative)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports invalid quantity (non-integer string)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: '5' }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'UNKNOWN', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice reports unknown SKU even with valid first line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'UNKNOWN', qty: 1 },
    ],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines array', () => {
  const inputLines = [{ sku: 'ICON-SET', qty: 2 }];
  const original = JSON.parse(JSON.stringify(inputLines));
  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: inputLines,
  });
  assert.deepEqual(inputLines, original);
});

test('createInvoice returns a new lines array (not the original)', () => {
  const inputLines = [{ sku: 'ICON-SET', qty: 2 }];
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: inputLines,
  });
  assert.notEqual(r.value.lines, inputLines);
  assert.notEqual(r.value.lines[0], inputLines[0]);
});

test('lineTotal multiplies qty by unitPrice', () => {
  const line = { qty: 2, unitPrice: 980 };
  assert.equal(lineTotal(line), 1960);
});

test('lineTotal handles qty of 1', () => {
  const line = { qty: 1, unitPrice: 8500 };
  assert.equal(lineTotal(line), 8500);
});

test('lineTotal handles large quantities', () => {
  const line = { qty: 100, unitPrice: 120000 };
  assert.equal(lineTotal(line), 12000000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 980 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1960);
  assert.equal(totals.total, 1960);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 980 },
      { qty: 1, unitPrice: 8500 },
      { qty: 3, unitPrice: 50 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1960 + 8500 + 150);
  assert.equal(totals.total, 1960 + 8500 + 150);
});

test('invoiceTotals with empty lines array', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns an object with both subtotal and total', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('subtotal' in totals);
  assert.ok('total' in totals);
});

test('addLine adds a new line to a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[1].qty, 1);
  assert.equal(r2.value.lines[1].name, 'Design work (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'ICON-SET', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'ICON-SET');
  assert.equal(r2.value.lines[0].qty, 5);
});

test('addLine validates qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 0 });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates qty is integer', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 1.5 });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'UNKNOWN', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'sent',
    lines: [{ sku: 'ICON-SET', qty: 1, name: 'Icon set (24 icons)', unitPrice: 980, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const original = JSON.parse(JSON.stringify(invoice));
  addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(invoice, original);
});

test('removeLine removes a line from a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  const invoice = r.value;
  const r2 = removeLine(invoice, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'ICON-SET');
});

test('removeLine reports LINE_NOT_FOUND', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = removeLine(invoice, 'UNKNOWN');
  assert.deepEqual(r2, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would be the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = removeLine(invoice, 'ICON-SET');
  assert.deepEqual(r2, { ok: false, error: 'NO_LINES' });
});

test('removeLine rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'sent',
    lines: [
      { sku: 'ICON-SET', qty: 1, name: 'Icon set (24 icons)', unitPrice: 980, vatRate: 21 },
      { sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
    ],
  };
  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  const invoice = r.value;
  const original = JSON.parse(JSON.stringify(invoice));
  removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(invoice, original);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.number, 'INV-2025-0001');
});

test('issueInvoice uses nextInvoiceNumber correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-03-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, ['INV-2025-0001', 'INV-2025-0002']);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2025-0003');
});

test('issueInvoice handles different years', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, ['INV-2025-0999']);
  assert.equal(r2.ok, true);
