test('lineDiscount calculates discount amount', () => {
  const line = { qty: 2, unitPrice: 980, discountPercent: 10 };
  // Line total: 2 * 980 = 1960, discount: 1960 * 10 / 100 = 196
  assert.equal(lineDiscount(line), 196);
});

test('lineDiscount defaults discountPercent to 0 if not provided', () => {
  const line = { qty: 2, unitPrice: 980 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount handles decimal discount percentages', () => {
  const line = { qty: 1, unitPrice: 1000, discountPercent: 12.5 };
  // Line total: 1000, discount: 1000 * 12.5 / 100 = 125
  assert.equal(lineDiscount(line), 125);
});

test('lineDiscount rounds fractional cents', () => {
  const line = { qty: 1, unitPrice: 1000, discountPercent: 33.33 };
  // Line total: 1000, discount: 1000 * 33.33 / 100 = 333.3 -> rounds to 333
  assert.equal(lineDiscount(line), 333);
});

test('lineDiscount clamps to 0 (never negative)', () => {
  const line = { qty: 0, unitPrice: 1000, discountPercent: 50 };
  // Line total: 0, discount: 0 (clamped)
  assert.equal(lineDiscount(line), 0);
});

test('invoiceTotals returns discount field', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 1000, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('discount' in totals);
});

test('invoiceTotals calculates single line discount', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 1000, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 2000, discount: 2000 * 10 / 100 = 200
  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 200);
  assert.equal(totals.total, 1800);
});

test('invoiceTotals sums discounts across multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, discountPercent: 10 },
      { qty: 1, unitPrice: 1000, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: subtotal 2000, discount 200
  // Line 2: subtotal 1000, discount 200
  // Total: subtotal 3000, discount 400, total 2600
  assert.equal(totals.subtotal, 3000);
  assert.equal(totals.discount, 400);
  assert.equal(totals.total, 2600);
});

test('invoiceTotals with mixed lines (some with discount, some without)', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, discountPercent: 10 },
      { qty: 1, unitPrice: 1000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: subtotal 1000, discount 100
  // Line 2: subtotal 1000, discount 0
  // Total: subtotal 2000, discount 100, total 1900
  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 100);
  assert.equal(totals.total, 1900);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000, discount: 1000, total: 0 (clamped)
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
