  assert.ok(text1.startsWith('DRAFT'));

  // Issued
  const r2 = issueInvoice(r1.value, []);
  const text2 = renderInvoiceText(r2.value);
  assert.ok(text2.startsWith('INV-2025-0001'));
});

test('renderInvoiceText shows VAT line when VAT > 0', () => {
  // ICON-SET has 21% VAT, gold customer gets 5% discount
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.includes('VAT: €'));
});

test('renderInvoiceText does not show VAT line when VAT = 0', () => {
  // PRINT-A4 has 0% VAT
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'PRINT-A4', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(!text.includes('VAT:'));
});

test('renderInvoiceText VAT appears before total line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  let vatLineIndex = -1;
  let totalLineIndex = -1;

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].startsWith('VAT:')) vatLineIndex = i;
    if (lines[i].startsWith('Total:')) totalLineIndex = i;
  }

  assert.ok(vatLineIndex !== -1, 'VAT line should exist');
  assert.ok(totalLineIndex !== -1, 'Total line should exist');
  assert.ok(vatLineIndex < totalLineIndex, 'VAT should come before Total');
});

test('renderInvoiceText calculates total including VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  // C-002 is standard tier (0% discount), ICON-SET is 980 cents with 21% VAT
  // Subtotal: 980, Discount: 0, VAT: 980 * 21 / 100 = 206, Total: 1186
  assert.ok(text.includes('€1,186.00') || text.includes('€11.86'));
});

test('renderInvoiceText with mixed VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
    ],
  });
  const text = renderInvoiceText(r.value);
  // ICON-SET: 21% VAT, PRINT-A4: 0% VAT
  // Should show VAT line because ICON-SET has VAT
  assert.ok(text.includes('VAT: €'));
});

